1	//! Pattern matching — 1:1 移植 `sqlite-source/src/func.c: patternCompare` + 公开入口
2	//! `sqlite3_strglob` / `sqlite3_strlike`。
3	//!
4	//! 对应 C 源码:
5	//! - `patternCompare`(`func.c:754-881`)
6	//! - `sqlite3_strglob`(`func.c:887-895`)
7	//! - `sqlite3_strlike`(`func.c:901-909`)
8	//! - `compareInfo`(`func.c:681-686`)
9	//! - `globInfo`/`likeInfoNorm`(`func.c:701-707`)
10	//!
11	//! # 行为契约(对齐 C)
12	//!
13	//! - 通配符:`*` (GLOB) 或 `%` (LIKE) 匹配零或多字符;`?` (GLOB) 或 `_` (LIKE) 匹配单字符
14	//! - `sqlite3_strlike` 第三参数 `esc` 指定 ESCAPE 字符,`esc==0` 时禁用 ESCAPE 处理
15	//! - LIKE 默认大小写不敏感(ASCII),GLOB 大小写敏感
16	//! - GLOB 还支持 `[...]` 字符集(本任务 spec 未要求,行为仍按 C 1:1 实现)
17	//! - 返回值是 `i32` 错误码,0 = 匹配,非 0 = 不匹配:
18	//!   - `SQLITE_MATCH = 0`             — 匹配
19	//!   - `SQLITE_NOMATCH = 1`           — 不匹配
20	//!   - `SQLITE_NOWILDCARDMATCH = 2`   — 模式含 `*`/`%` 但仍不匹配(C 版内部使用)
21	//!
22	//! # 实现说明
23	//!
24	//! C 端用 `const u8*` 指针 + `Utf8Read` 宏做 UTF-8 解码。Rust 端用
25	//! `Cursor<&[u8]>` 抽象,内含字节切片和位置索引;`read_utf8` 等价于
26	//! `Utf8Read(z)` 的副作用。递归调用通过传递切片 + 位置实现。
27	
28	// ----------------------------------------------------------------------------
29	// 结果码(对齐 `func.c:712-714` 的内部宏,非 sqlite.h 中的错误码)
30	// ----------------------------------------------------------------------------
31	
32	/// `SQLITE_MATCH` — 模式匹配。
33	pub const SQLITE_MATCH: i32 = 0;
34	/// `SQLITE_NOMATCH` — 模式不匹配。
35	pub const SQLITE_NOMATCH: i32 = 1;
36	/// `SQLITE_NOWILDCARDMATCH` — 含通配符的模式不匹配(C 内部用)。
37	pub const SQLITE_NOWILDCARDMATCH: i32 = 2;
38	
39	// ----------------------------------------------------------------------------
40	// compareInfo(对齐 `func.c:681-686`)
41	// ----------------------------------------------------------------------------
42	
43	/// 描述一个 glob/like 模式的元数据。
44	///
45	/// 字段顺序对齐 C 端 `struct compareInfo`。
46	#[derive(Clone, Copy)]
47	struct CompareInfo {
48	    /// `*` (GLOB) 或 `%` (LIKE) — 匹配零或多字符。
49	    match_all: u8,
50	    /// `?` (GLOB) 或 `_` (LIKE) — 匹配单字符。
51	    match_one: u8,
52	    /// 字符集起始符(GLOB 为 `[`,LIKE 为 `0`)。0 表示不支持字符集。
53	    match_set: u8,
54	    /// 大小写不敏感(仅 ASCII:LIKE = 1,GLOB = 0)。
55	    no_case: u8,
56	}
57	
58	const GLOB_INFO: CompareInfo = CompareInfo {
59	    match_all: b'*',
60	    match_one: b'?',
61	    match_set: b'[',
62	    no_case: 0,
63	};
64	
65	const LIKE_INFO_NORM: CompareInfo = CompareInfo {
66	    match_all: b'%',
67	    match_one: b'_',
68	    match_set: 0,
69	    no_case: 1,
70	};
71	
72	// ----------------------------------------------------------------------------
73	// 公开 API
74	// ----------------------------------------------------------------------------
75	
76	/// `int sqlite3_strglob(const char *zGlobPattern, const char *zString)`
77	///
78	/// 匹配则返回 `SQLITE_MATCH`(0),否则返回 `SQLITE_NOMATCH` 或
79	/// `SQLITE_NOWILDCARDMATCH`。
80	///
81	/// `Option::None` 对应 C 端 `NULL` 指针。
82	pub fn sqlite3_strglob(z_glob_pattern: Option<&[u8]>, z_string: Option<&[u8]>) -> i32 {
83	    if z_string.is_none() {
84	        // zString==0 → return zGlobPattern!=0;
85	        return if z_glob_pattern.is_none() {
86	            SQLITE_MATCH
87	        } else {
88	            SQLITE_NOMATCH
89	        };
90	    }
91	    let pat = match z_glob_pattern {
92	        Some(p) => p,
93	        None => return SQLITE_NOMATCH, // zGlobPattern==0 → return 1;
94	    };
95	    pattern_compare(pat, z_string.unwrap(), &GLOB_INFO, b'[' as u32)
96	}
97	
98	/// `int sqlite3_strlike(const char *zPattern, const char *zStr, unsigned int esc)`
99	///
100	/// 匹配则返回 `SQLITE_MATCH`(0)。`esc==0` 禁用 ESCAPE 字符。
101	///
102	/// `Option::None` 对应 C 端 `NULL` 指针。
103	pub fn sqlite3_strlike(z_pattern: Option<&[u8]>, z_str: Option<&[u8]>, esc: u32) -> i32 {
104	    if z_str.is_none() {
105	        return if z_pattern.is_none() {
106	            SQLITE_MATCH
107	        } else {
108	            SQLITE_NOMATCH
109	        };
110	    }
111	    let pat = match z_pattern {
112	        Some(p) => p,
113	        None => return SQLITE_NOMATCH,
114	    };
115	    pattern_compare(pat, z_str.unwrap(), &LIKE_INFO_NORM, esc)
116	}
117	
118	// ----------------------------------------------------------------------------
119	// 内部:patternCompare
120	// ----------------------------------------------------------------------------
121	
122	/// `patternCompare` 的 1:1 Rust 翻译。
123	///
124	/// `pat` 和 `s` 是当前剩余的字节切片(递归时调整);`pi`/`si` 是当前位置。
125	fn pattern_compare(pat: &[u8], s: &[u8], info: &CompareInfo, match_other: u32) -> i32 {
126	    let mut pc = Cursor::new(pat);
127	    let mut sc = Cursor::new(s);
128	    pattern_compare_inner(&mut pc, &mut sc, info, match_other)
129	}
130	
131	fn pattern_compare_inner(
132	    pc: &mut Cursor<'_>,
133	    sc: &mut Cursor<'_>,
134	    info: &CompareInfo,
135	    match_other: u32,
136	) -> i32 {
137	    let match_all = info.match_all as u32;
138	    let match_one = info.match_one as u32;
139	    let no_case = info.no_case != 0;
140	
141	    loop {
142	        let c = pc.read_utf8();
143	        if c == 0 {
144	            // 模式串耗尽
145	            return if sc.peek() == 0 {
146	                SQLITE_MATCH
147	            } else {
148	                SQLITE_NOMATCH
149	            };
150	        }
151	
152	        if c == match_all {
153	            // 跳过多个连续的 match_all(match_one 也吞一个字符)
154	            let mut c2 = pc.read_utf8();
155	            while c2 == match_all || (c2 == match_one && match_one != 0) {
156	                if c2 == match_one && sc.read_utf8() == 0 {
157	                    return SQLITE_NOWILDCARDMATCH;
158	                }
159	                c2 = pc.read_utf8();
160	            }
161	            if c2 == 0 {
162	                return SQLITE_MATCH; // "*" 在末尾
163	            }
164	            if c2 as u32 == match_other {
165	                if info.match_set == 0 {
166	                    // LIKE 的 ESCAPE:消耗下一个字符作字面量
167	                    let next_c = pc.read_utf8();
168	                    if next_c == 0 {
169	                        return SQLITE_NOWILDCARDMATCH;
170	                    }
171	                    // 把 pc 回退到 next_c 之前(以便后续走字面量匹配)
172	                    // 实际上 match_other 在 LIKE 中是 esc,esc 后面那个字面字符需要匹配一次
173	                    // 此时 pc 已经在 next_c 之后,我们需要在外部循环里直接比较 c2=esc 后
174	                    // 的字符和输入。简化:把 next_c 当作要匹配的字符,直接比较。
175	                    // 但需要保持 zEscaped 语义 — C 版本靠 zEscaped 指针位置判断"是否
176	                    // 来自 escape",我们的等价为:c2==match_one 时检查 zPattern!=zEscaped。
177	                    // 我们用 cursor 抽象后简化:在这里直接走"字面量匹配"分支。
178	                    let c2_str = sc.read_utf8();
179	                    if next_c == c2_str {
180	                        continue;
181	                    }
182	                    if no_case
183	                        && next_c < 0x80
184	                        && c2_str < 0x80
185	                        && ascii_to_lower(next_c) == ascii_to_lower(c2_str)
186	                    {
187	                        continue;
188	                    }
189	                    return SQLITE_NOMATCH;
190	                } else {
191	                    // GLOB 的 "*[" 情况:慢速递归搜索
192	                    // 此时 pc 已经在 '[' 之后,需要回退 1 字节从 '[' 开始重新匹配
193	                    // (对齐 C 端 `&zPattern[-1]`)
194	                    if !pc.rewind_one() {
195	                        return SQLITE_NOWILDCARDMATCH;
196	                    }
197	                    let saved_sc_pos = sc.pos;
198	                    while sc.peek() != 0 {
199	                        let mut pc_inner = pc.clone();
200	                        let mut sc_inner = sc.clone();
201	                        let r =
202	                            pattern_compare_inner(&mut pc_inner, &mut sc_inner, info, match_other);
203	                        if r != SQLITE_NOMATCH {
204	                            return r;
205	                        }
206	                        // SKIP_UTF8(zString)
207	                        if sc.read_utf8() == 0 {
208	                            break;
209	                        }
210	                        // 防止死循环:如果 read_utf8 没推进,break
211	                        if sc.pos == saved_sc_pos {
212	                            break;
213	                        }
214	                    }
215	                    return SQLITE_NOWILDCARDMATCH;
216	                }
217	            }
218	
219	            // 搜索输入串中第一个匹配 c2 的位置,递归
220	            if c2 < 0x80 {
221	                // ASCII 快速路径:用"扫描匹配"代替逐字符递归
222	                let (zstop_upper, zstop_lower) = if no_case {
223	                    (ascii_to_upper(c2) as u8, ascii_to_lower(c2) as u8)
224	                } else {
225	                    (c2 as u8, c2 as u8)
226	                };
227	                loop {
228	                    // 找到第一个 == zstop 的字节(大小写不敏感时还要查 zstop 的另一种 case)
229	                    let found = sc.find_byte_case(zstop_upper, zstop_lower, no_case);
230	                    match found {
231	                        Some(idx) => {
232	                            // 跳过那个匹配的字节,然后从那里递归
233	                            sc.pos = idx + 1;
234	                            let mut pc_inner = pc.clone();
235	                            let mut sc_inner = sc.clone();
236	                            let r = pattern_compare_inner(
237	                                &mut pc_inner,
238	                                &mut sc_inner,
239	                                info,
240	                                match_other,
241	                            );
242	                            if r != SQLITE_NOMATCH {
243	                                return r;
244	                            }
245	                            // 继续找下一个匹配点(sc.pos 已经在 idx+1)
246	                        }
247	                        None => return SQLITE_NOWILDCARDMATCH,
248	                    }
249	                }
250	            } else {
251	                // 多字节 UTF-8 字符:逐字符扫描
252	                loop {
253	                    let c3 = sc.read_utf8();
254	                    if c3 == 0 {
255	                        return SQLITE_NOWILDCARDMATCH;
256	                    }
257	                    if c3 == c2 {
258	                        let mut pc_inner = pc.clone();
259	                        let mut sc_inner = sc.clone();
260	                        let r = pattern_compare_inner(
261	                            &mut pc_inner,
262	                            &mut sc_inner,
263	                            info,
264	                            match_other,
265	                        );
266	                        if r != SQLITE_NOMATCH {
267	                            return r;
268	                        }
269	                    }
270	                }
271	            }
272	        }
273	
274	        if c as u32 == match_other {
275	            if info.match_set == 0 {
276	                // ESCAPE 字符(LIKE 模式)
277	                let next_c = pc.read_utf8();
278	                if next_c == 0 {
279	                    return SQLITE_NOMATCH;
280	                }
281	                pc.mark_escaped();
282	                // 字面量匹配:把 next_c 当作普通字符
283	                let c2_str = sc.read_utf8();
284	                if next_c == c2_str {
285	                    continue;
286	                }
287	                if no_case
288	                    && next_c < 0x80
289	                    && c2_str < 0x80
290	                    && ascii_to_lower(next_c) == ascii_to_lower(c2_str)
291	                {
292	                    continue;
293	                }
294	                return SQLITE_NOMATCH;
295	            } else {
296	                // GLOB 的 [...] 字符集
297	                let str_c = sc.read_utf8();
298	                if str_c == 0 {
299	                    return SQLITE_NOMATCH;
300	                }
301	                let mut set_c = pc.read_utf8();
302	                let mut invert = 0u8;
303	                if set_c == b'^' as u32 {
304	                    invert = 1;
305	                    set_c = pc.read_utf8();
306	                }
307	                let mut seen = 0u8;
308	                if set_c == b']' as u32 {
309	                    if str_c == b']' as u32 {
310	                        seen = 1;
311	                    }
312	                    set_c = pc.read_utf8();
313	                }
314	                let mut prior_c: u32 = 0;
315	                while set_c != 0 && set_c != b']' as u32 {
316	                    if set_c == b'-' as u32
317	                        && pc.peek() != b']'
318	                        && pc.peek() != 0
319	                        && prior_c > 0
320	                    {
321	                        let end_c = pc.read_utf8();
322	                        if str_c >= prior_c && str_c <= end_c {
323	                            seen = 1;
324	                        }
325	                        prior_c = 0;
326	                    } else {
327	                        if str_c == set_c {
328	                            seen = 1;
329	                        }
330	                        prior_c = set_c;
331	                    }
332	                    set_c = pc.read_utf8();
333	                }
334	                if set_c == 0 || (seen ^ invert) == 0 {
335	                    return SQLITE_NOMATCH;
336	                }
337	                continue;
338	            }
339	        }
340	
341	        // 普通字面量匹配
342	        let c2_str = sc.read_utf8();
343	        if c == c2_str {
344	            continue;
345	        }
346	        if no_case
347	            && c < 0x80
348	            && c2_str < 0x80
349	            && ascii_to_lower(c) == ascii_to_lower(c2_str)
350	        {
351	            continue;
352	        }
353	        if c as u32 == match_one && !pc.is_escaped() && c2_str != 0 {
354	            pc.clear_escaped();
355	            continue;
356	        }
357	        return SQLITE_NOMATCH;
358	    }
359	}
360	
361	// ----------------------------------------------------------------------------
362	// Cursor:在字节切片上模拟 C 端 `const u8*` 指针
363	// ----------------------------------------------------------------------------
364	
365	#[derive(Clone)]
366	struct Cursor<'a> {
367	    bytes: &'a [u8],
368	    pos: usize,
369	    /// 对齐 C 端 `zEscaped`:`_`/`?` 紧跟 ESCAPE 字符后不算单字符通配。
370	    escaped: bool,
371	}
372	
373	impl<'a> Cursor<'a> {
374	    fn new(bytes: &'a [u8]) -> Self {
375	        Self {
376	            bytes,
377	            pos: 0,
378	            escaped: false,
379	        }
380	    }
381	
382	    fn peek(&self) -> u8 {
383	        if self.pos < self.bytes.len() {
384	            self.bytes[self.pos]
385	        } else {
386	            0
387	        }
388	    }
389	
390	    /// `Utf8Read(z)` — 读一个 UTF-8 码点,推进 pos。
391	    fn read_utf8(&mut self) -> u32 {
392	        if self.pos >= self.bytes.len() {
393	            return 0;
394	        }
395	        let c = self.bytes[self.pos];
396	        if c < 0x80 {
397	            self.pos += 1;
398	            return c as u32;
399	        }
400	        // sqlite3Utf8Read 路径
401	        // SAFETY(csssan): 上面已经确认 pos < len,后续读取都在 [pos, len) 内
402	        // 多字节时不会越界因为 `while (*pz & 0xc0)==0x80` 在遇到非延续字节时停止
403	        let mut codepoint = UTF8_TRANS1[(c - 0xc0) as usize] as u32;
404	        self.pos += 1;
405	        while self.pos < self.bytes.len() && (self.bytes[self.pos] & 0xc0) == 0x80 {
406	            codepoint = (codepoint << 6) + (0x3f & self.bytes[self.pos] as u32);
407	            self.pos += 1;
408	        }
409	        if codepoint < 0x80
410	            || (codepoint & 0xFFFF_F800) == 0xD800
411	            || (codepoint & 0xFFFF_FFFE) == 0xFFFE
412	        {
413	            codepoint = 0xFFFD;
414	        }
415	        codepoint
416	    }
417	
418	    /// `SQLITE_SKIP_UTF8(z)`:前进 1 个 UTF-8 字符。
419	    /// 实际就是 `read_utf8` 丢掉结果。
420	    #[allow(dead_code)]
421	    fn skip_utf8(&mut self) {
422	        self.read_utf8();
423	    }
424	
425	    /// 回退 1 字节。返回 false 表示已经在 0 位置。
426	    fn rewind_one(&mut self) -> bool {
427	        if self.pos == 0 {
428	            return false;
429	        }
430	        self.pos -= 1;
431	        true
432	    }
433	
434	    /// ASCII 范围内找第一个 == target 的字节(从 pos 开始)。
435	    /// 若 no_case,还匹配 target 的相反 case。
436	    /// 返回 Some(idx) 找到,None 表示没找到。
437	    fn find_byte_case(&self, upper: u8, lower: u8, no_case: bool) -> Option<usize> {
438	        let start = self.pos;
439	        let bytes = &self.bytes[start..];
440	        for (i, &b) in bytes.iter().enumerate() {
441	            if b == upper {
442	                return Some(start + i);
443	            }
444	            if no_case && b == lower {
445	                return Some(start + i);
446	            }
447	        }
448	        None
449	    }
450	
451	    fn mark_escaped(&mut self) {
452	        self.escaped = true;
453	    }
454	
455	    fn is_escaped(&self) -> bool {
456	        self.escaped
457	    }
458	
459	    fn clear_escaped(&mut self) {
460	        self.escaped = false;
461	    }
462	}
463	
464	// ----------------------------------------------------------------------------
465	// ASCII case fold
466	// ----------------------------------------------------------------------------
467	
468	#[inline]
469	fn ascii_to_upper(c: u32) -> u32 {
470	    if c >= b'a' as u32 && c <= b'z' as u32 {
471	        c - 0x20
472	    } else {
473	        c
474	    }
475	}
476	
477	#[inline]
478	fn ascii_to_lower(c: u32) -> u32 {
479	    if c >= b'A' as u32 && c <= b'Z' as u32 {
480	        c + 0x20
481	    } else {
482	        c
483	    }
484	}
485	
486	// ----------------------------------------------------------------------------
487	// sqlite3Utf8Trans1(`utf.c:52-61`)
488	// ----------------------------------------------------------------------------
489	
490	const UTF8_TRANS1: [u8; 64] = [
491	    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
492	    0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f,
493	    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
494	    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x00, 0x01, 0x02, 0x03, 0x00, 0x01, 0x00, 0x00,
495	];
496	
497	// ----------------------------------------------------------------------------
498	// 单元测试(快速冒烟,完整测试在 tests/util/pattern.rs)
499	// ----------------------------------------------------------------------------
500	
501	#[cfg(test)]
502	mod tests {
503	    use super::*;
504	
505	    fn sg(pat: &str, s: &str) -> i32 {
506	        sqlite3_strglob(Some(pat.as_bytes()), Some(s.as_bytes()))
507	    }
508	    fn sl(pat: &str, s: &str, esc: u32) -> i32 {
509	        sqlite3_strlike(Some(pat.as_bytes()), Some(s.as_bytes()), esc)
510	    }
511	
512	    #[test]
513	    fn strglob_basic() {
514	        assert_eq!(sg("a*", "abc"), SQLITE_MATCH);
515	        assert_eq!(sg("a*", "bc"), SQLITE_NOWILDCARDMATCH);
516	        assert_eq!(sg("?", "a"), SQLITE_MATCH);
517	        assert_eq!(sg("?", ""), SQLITE_NOMATCH);
518	    }
519	
520	    #[test]
521	    fn strlike_basic() {
522	        assert_eq!(sl("a%", "abc", 0), SQLITE_MATCH);
523	        assert_eq!(sl("a_", "abc", 0), SQLITE_NOMATCH);
524	        assert_eq!(sl("a_", "ab", 0), SQLITE_MATCH);
525	    }
526	
527	    #[test]
528	    fn strlike_case_insensitive() {
529	        assert_eq!(sl("ABC", "abc", 0), SQLITE_MATCH);
530	        assert_eq!(sl("AbC", "aBc", 0), SQLITE_MATCH);
531	    }
532	
533	    #[test]
534	    fn strlike_escape() {
535	        // ESCAPE 转义 %
536	        assert_eq!(sl("a\\%b", "a%b", b'\\' as u32), SQLITE_MATCH);
537	        assert_eq!(sl("a\\%b", "axb", b'\\' as u32), SQLITE_NOMATCH);
538	    }
539	
540	    #[test]
541	    fn strlike_escape_zero_disables_escape() {
542	        // esc=0 时,任何字符都是字面量
543	        assert_eq!(sl("a%b", "axb", 0), SQLITE_MATCH);
544	        assert_eq!(sl("a%b", "a%b", 0), SQLITE_MATCH);
545	    }
546	}
