1	//! `tests/util/pattern.rs` — sqlite3_strglob / sqlite3_strlike严格对齐 C行为测试。
2	//!
3	//! 本文件用 `oracle/sqlite3`同样的输入跑 Rust 实现,
4	//! 每个测试在文档注释里标出 C端 `func.c` 行号 +期望返回值。
5	//!
6	//! 注意:C端定义在 `func.c:712-714`:
7	//! ```c
8	//! #define SQLITE_MATCH0
9	//! #define SQLITE_NOMATCH1
10	//! #define SQLITE_NOWILDCARDMATCH2
11	//! ```
12	//! 这与 spec 中提到的"SQLITE_NOMATCH(27)"不同 — spec 把 SQLITE_NOTICE(27)误标了;
13	//!实际 pattern 比较的失败返回1 或2,不是27。我们以 C源码为准。
14	
15	use libsqlite_rs::{
16	 sqlite3_strglob, sqlite3_strlike, SQLITE_MATCH, SQLITE_NOMATCH, SQLITE_NOWILDCARDMATCH,
17	};
18	
19	// ============================================================================
20	//1. sqlite3_strglob: `a*`匹配 `abc` → MATCH (func.c:887-895)
21	// ============================================================================
22	#[test]
23	fn strglob_star_matches_abc() {
24	 let r = sqlite3_strglob(Some(b"a*"), Some(b"abc"));
25	 assert_eq!(r, SQLITE_MATCH, "a* must match abc");
26	}
27	
28	// ============================================================================
29	//2. sqlite3_strglob: `a*` 不匹配 `bc` → NOMATCH
30	//    C 行为验证:实际 sqlite3_strglob("a*", "bc") == 1 (SQLITE_NOMATCH)
31	//    说明:虽然 pattern 含 '*',但 C 版在找不到首字符 'a' 后 break,
32	//    外层 fallthrough 返回 SQLITE_NOWILDCARDMATCH(2)... 但实际编译调用
33	//    sqlite3_strglob("a*", "bc") 返回 1。修正:期望 SQLITE_NOMATCH(1)。
34	// ============================================================================
35	#[test]
36	fn strglob_star_no_match_returns_nowildcard() {
37	 let r = sqlite3_strglob(Some(b"a*"), Some(b"bc"));
38	 assert_eq!(
39	 r, SQLITE_NOMATCH,
40	 "a* must not match bc — verified against C sqlite3_strglob (returns 1)"
41	 );
42	}
43	
44	// ============================================================================
45	//3. sqlite3_strglob: 空 pattern匹配空串 → MATCH
46	// ============================================================================
47	#[test]
48	fn strglob_empty_pattern_matches_empty_string() {
49	 let r = sqlite3_strglob(Some(b""), Some(b""));
50	 assert_eq!(r, SQLITE_MATCH);
51	}
52	
53	// ============================================================================
54	//4. sqlite3_strglob: `?`匹配单字符 `a`
55	// ============================================================================
56	#[test]
57	fn strglob_question_matches_single_char() {
58	 assert_eq!(sqlite3_strglob(Some(b"?"), Some(b"a")), SQLITE_MATCH);
59	}
60	
61	// ============================================================================
62	//5. sqlite3_strglob: `?` 不匹配空串 → NOMATCH
63	// ============================================================================
64	#[test]
65	fn strglob_question_no_match_empty() {
66	 assert_eq!(sqlite3_strglob(Some(b"?"), Some(b"")), SQLITE_NOMATCH);
67	}
68	
69	// ============================================================================
70	//6. sqlite3_strglob: `abc` 字面量匹配 `abc`
71	// ============================================================================
72	#[test]
73	fn strglob_literal_match() {
