}

// ============================================================================
//19. sqlite3_strlike: `_` 与 `%`混合
// ============================================================================
#[test]
fn strlike_mixed_underscore_percent() {
 assert_eq!(
 sqlite3_strlike(Some(b"a_%b"), Some(b"abc"),0),
