}

// ============================================================================
//21. sqlite3_strglob:模式消耗比输入多(单字节)
// ============================================================================
#[test]
fn strglob_pattern_longer_than_input() {
 assert_eq!(
 sqlite3_strglob(Some(b"abcdef"), Some(b"abc")),
