//16. sqlite3_strglob: `*` 在末尾匹配任意后缀
// ============================================================================
#[test]
fn strglob_trailing_star() {
 assert_eq!(sqlite3_strglob(Some(b"*.txt"), Some(b"a.txt")), SQLITE_MATCH);
 assert_eq!(
 sqlite3_strglob(Some(b"*.txt"), Some(b"a.csv")),
 SQLITE_NOWILDCARDMATCH
 );
}

