#[test]
fn strlike_null_string_handling() {
 assert_eq!(sqlite3_strlike(Some(b"a%"), None,0), SQLITE_NOMATCH);
 assert_eq!(sqlite3_strlike(None, None,0), SQLITE_MATCH);
 assert_eq!(sqlite3_strlike(None, Some(b"abc"),0), SQLITE_NOMATCH);
}

