// ============================================================================
//23. sqlite3_strlike:字节值 >=0x80(UTF-8 多字节)literal match
// ============================================================================
#[test]
fn strlike_utf8_literal() {
 // "中文" 是 UTF-8 多字节序列
 let pat = "中文".as_bytes();
 let s = "中文".as_bytes();
 assert_eq!(sqlite3_strlike(Some(pat), Some(s),0), SQLITE_MATCH);
 assert_eq!(
 sqlite3_strlike(Some(pat), Some("中x".as_bytes()),0),
 SQLITE_NOMATCH
 );
}
